# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 post','在……之后；在后面']]
W=[
E('posterior','英 /pɒˈtɪəriə/；美 /pɑˈtɪriər/','后面的；后部的；臀部〔委婉说法〕；后验的','先确定一个前面，再沿着身体、时间或推理过程找后面。','借自拉丁 posterior，posterus 后来的的比较级，上接 post；不是英语 poster 海报加 -ior。',B+[['拉丁 posterus → posterior','后来的 → 更后面的'],['英语 posterior','后部的；臀部；后验的']],'the posterior part 是后部；在解剖中常与 anterior 前部的相对。作名词可委婉指臀部；统计学中的 posterior probability 是获得相关证据后更新的概率，重点是信息顺序。','the posterior surface；the posterior part；a posterior probability；land on one’s posterior。','posterior 不是 poster 海报的比较级。人体的前后方向、时间先后和统计后验要按语境分别理解。',('The diagram labels the anterior and posterior surfaces.','图中标出了前表面和后表面。'),('He slipped on the ice and landed on his posterior.','他在冰上滑倒，一屁股坐到了地上。'),sources=['https://www.etymonline.com/word/posterior','https://en.wiktionary.org/wiki/posterior']),
E('posterity','英 /pɒˈsterəti/；美 /pɑˈsterəti/','后世；后代；子孙','想象时间轴继续向前走，我们之后还会有一代代人来到这里。','来自法语 posterité、拉丁 posteritas，上接 posterus 后来的；不从英语 posterior 再直接加 -ity。',B+[['拉丁 posterus → posteritas','后来的 → 后代、未来世代'],['法语 posterité → 英语 posterity','后世；后人']],'preserve something for posterity 是把东西保留下来给后人；posterity will judge us 是说后世会评价我们。它可指一个人的后代，也常泛指未来世代。','for posterity；preserve for posterity；leave something to posterity。','posterity 是后世的人，prosperity 是繁荣；两者形近，但一个关乎时间，一个关乎兴旺。',('The recordings were preserved for posterity.','这些录音被保存下来，留给后人。'),('He hoped his letters would help posterity understand the period.','他希望自己的书信能帮助后人理解那个时代。'),sources=['https://www.etymonline.com/word/posterity','https://en.wiktionary.org/wiki/posterity']),
E('postscript','英 /ˈpəʊstskrɪpt/；美 /ˈpoʊstskrɪpt/','附言；补记；后续补充','信已经写完签名了，忽然想起一件事，于是在末尾再补几句。','接拉丁 post scriptum 写在后面的内容，post 之后 + scriptum 已写的；现代可对应 post- + script。',B+[['拉丁 post scriptum → postscriptum','写完之后补写的内容'],['英语 postscript','信末附言；后来的补充']],'a postscript to a letter 是信末附言，常用 P.S. 引出。a postscript to the story 也可指主要故事结束后的补充，让听者知道后来又发生了什么。','add a postscript；in a postscript；a postscript to the story；P.S.。','postscript 不等于文章前面的 preface。它位于主要内容之后，可能只是几句话，不一定是一整章。',('She added a postscript asking me to bring the photographs.','她在信末加了附言，让我把照片带来。'),('The final chapter serves as a postscript to the main story.','最后一章相当于主线故事的补记。'),sources=['https://www.etymonline.com/word/postscript','https://en.wiktionary.org/wiki/postscript']),
E('posthumous','英 /ˈpɒstʃʊməs/；美 /ˈpɑstʃəməs/','死后发生的；身后出版或授予的；遗腹的','人已经不在，作品、荣誉或孩子却在之后来到世上。','来自拉丁 postumus 最后的、最后出生的；后期受 humare 埋葬或 humus 土的联想加 h。不是原本就由 post + humus 规则合成。',B+[['拉丁 posterus → postumus','后来的 → 最后的、最后出生的'],['后期拉丁 posthumus → 英语 posthumous','与身后发生、父死后出生相联系']],'a posthumous award 是去世后授予的奖；a posthumous novel 是作者去世后出版的小说，通常不是说作者死后才写作。posthumous child 可指父亲去世后出生的孩子。','a posthumous award；a posthumous publication；a posthumous album；a posthumous child。','posthumous 中的 h 有后来的词源联想背景，不能据现代拼写编成最初就是“埋进土后”。重音在第一音节。',('The writer received a posthumous award for her contribution to literature.','这位作家去世后因文学贡献获得了追授奖项。'),('His posthumous novel was edited from an unfinished manuscript.','他身后出版的小说由一份未完成的手稿编辑而成。'),sources=['https://www.etymonline.com/word/posthumous','https://en.wiktionary.org/wiki/posthumous']),
E('posthumously','英 /ˈpɒstʃʊməsli/；美 /ˈpɑstʃəməsli/','在死后；于身后','把时间点标在某人去世之后，说明出版、授奖或认可发生得更晚。','posthumous + -ly；形容词的历史接 postumus 与后来的 h 拼写变化。',B+[['拉丁 postumus／posthumus → posthumous','最后的 → 身后的'],['posthumous + -ly → posthumously','在身后发生']],'published posthumously 是死后出版；awarded posthumously 是追授。副词通常修饰这些动作，告诉你动作发生在谁去世之后。','published posthumously；awarded posthumously；honored posthumously。','a posthumous award 用形容词修饰奖项，receive an award posthumously 用副词说明授奖时间；意思相通，句法不同。',('The collection of poems was published posthumously.','这部诗集在作者去世后出版。'),('The medal was awarded posthumously to the rescue worker.','这枚奖章被追授给了那位救援人员。'),sources=['https://www.etymonline.com/word/posthumous','https://www.oxfordlearnersdictionaries.com/definition/english/posthumously']),
E('postwar','英 /ˈpəʊstwɔː/；美 /ˈpoʊstwɔr/','战后的','战争结束是时间轴上的一道分界，之后的重建、生活和文化都可以用这个词描述。','post- 之后 + war 战争；属于英语用拉丁前缀与日常词组成的新词，不是古罗马整词。',B+[['英语 post- + war → postwar','战争结束之后的']],'postwar reconstruction 是战后重建；the postwar generation 是战后的一代人。不加说明时，某些历史文本常指第二次世界大战后，但具体是哪场战争仍由上下文决定。','postwar reconstruction；postwar Europe；the postwar economy；the postwar generation。','postwar 不等于 after every war，也不是“下一场战争”。它相对于谈论中的那场战争，表示之后的时期。',('The museum documents postwar reconstruction in the city.','博物馆记录了这座城市的战后重建。'),('Her research focuses on postwar housing design.','她的研究集中在战后住宅设计。'),sources=['https://www.merriam-webster.com/dictionary/postwar','https://en.wiktionary.org/wiki/postwar']),
E('postponed','英 /pəˈspəʊnd/；美 /poʊˈspoʊnd/','被推迟的；已经延期的','把日历上的安排从现在这格移到后面的某一格。','postpone + -ed；postpone 接拉丁 postponere，post 后面 + ponere 放，把事情往后放。',B+[['拉丁 postponere → 英语 postpone','放到后面 → 推迟'],['postpone + -ed → postponed','已经推迟']],'The meeting was postponed 是会议延期了；postponed until Friday 是推到星期五。这个词说明原时间不再举行，但不表示事情永远取消。','be postponed until；be postponed because of；a postponed meeting。','postponed 是推后，canceled 是取消。postponed indefinitely 表示新时间未定，也不必自动理解为永不举行。',('The concert was postponed until next month.','音乐会被推迟到下个月。'),('The meeting was postponed because several members could not attend.','因为几位成员无法参加，会议延期了。'),sources=['https://www.etymonline.com/word/postpone','https://www.oxfordlearnersdictionaries.com/definition/english/postpone']),
E('postpaid','英 /ˌpəʊstˈpeɪd/；美 /ˌpoʊstˈpeɪd/','后付费的；邮资已付的〔另一构词〕','手机服务是先用后付；邮购说明则可能说邮费已经算进价钱，两条线要分开看。','后付费义是 post- 之后 + paid 已付；邮资义则是 post 邮政 + paid。这里两个 post 来源和作用不同。',[['后付费义：拉丁 post → 英语 post- + paid','服务之后再付款'],['邮资义：英语 post〔邮件〕+ paid','邮费已付或已包含']],'a postpaid mobile plan 是按账单后付费的手机套餐；The book costs ten dollars postpaid 可以表示书价十美元且包含邮资。不能把后一种说明误读成收书以后再交钱。','a postpaid plan；postpaid customers；sent postpaid；a price quoted postpaid。','postpaid 在通信套餐里与 prepaid 预付费相对；在邮寄语境里却可能强调已经付了邮费。只按前缀记忆会在这里误判。',('She switched from a prepaid plan to a postpaid plan.','她从预付费套餐改成了后付费套餐。'),('The booklet is available for five dollars postpaid.','这本小册子售价五美元，含邮资。'),sources=['https://en.wiktionary.org/wiki/postpaid','https://www.merriam-webster.com/dictionary/postpaid'])
]
